import moment from "moment";
import { useCallback, useEffect, useState } from "react";
import { Button, Card, Container, Form, InputGroup } from "react-bootstrap";
import { useNavigate, useParams } from "react-router-dom";

export const useCalendarFunctions = (marksSet, setDate, navigate) => {
  function formatDate(date) {
    return moment(date).format("YYYY-MM-DD");
  }

  const handleChange = useCallback((selectDate) => {
    setDate(formatDate(selectDate));
  }, []);

  return { handleChange };
};

export const dailyData = () => {
  const key = [];
  for (let i = 0; i < localStorage.length; i++) {
    let currentKey = localStorage.key(i);
    if (moment(currentKey, "YYYY-MM-DD", true).isValid()) {
      key.push(currentKey);
    }
  }
  return key;
};

export function SelectDate() {
  let [inputtext, setInputText] = useState("");
  let [textList, setTextList] = useState([]);
  let [checkList, setCheckList] = useState([]);

  let date = useParams();

  const handleText = (e) => {
    setInputText(e.target.value);
  };
  /////저장//////

  let navigate = useNavigate();
  const saveData = () => {
    const dataset = {
      checkList: checkList,
      textList: textList,
    };
    if (isEmpty(textList) || isEmpty(checkList)) {
      localStorage.removeItem(date.date);
      navigate("/");
    } else localStorage.setItem(date.date, JSON.stringify(dataset));
    navigate("/");
  };
  /// 배열 비어있는지 확인 ///
  function isEmpty(arr) {
    return !arr || arr.length === 0;
  }

  //// 미리 정보가 있는지 확인 ////
  useEffect(() => {
    let test = JSON.parse(localStorage.getItem(date.date));
    if (test) {
      setCheckList(test.checkList || []);
      setTextList(test.textList || []);
    }

  }, [date.date]);
  ///추가함수///
  const addData = () => {
    if (inputtext.trim() === "") return;
    setTextList([...textList, inputtext]);
    setCheckList([...checkList, false]);
  };
  ////삭제함수////
  const deleteData = (index) => {
    let textcopy = [...textList];
    let checkcopy = [...checkList];
    checkcopy.splice(index, 1);
    textcopy.splice(index, 1);
    setTextList(textcopy);
    setCheckList(checkcopy);
  };
  ////체크박스//////
  const checkListBox = (index) => {
    let copy = [...checkList]; // 기존 checkList를 복사
    copy[index] = !copy[index]; // 해당 index의 값을 토글 (true <-> false)
    setCheckList(copy); // 상태 업데이트
    checkpoint(index,copy[index]);
  };
  const checkpoint = (index ,state)=> {
    console.log(`${index} ${state}`);
  }

  return (
    <div className="bg">
      <Container>
        <h2 className="font fontheader">TO DO LIST </h2>
        <h4 className="d-flex justify-content-end me-3 font line"> {date.date}</h4>
        <InputGroup className=" w-75 mb-4 ms-auto me-3">
          <Form.Control
            className="font2"
            placeholder="입력해주세요"
            onChange={handleText}
          />
          <Button
            className="font2"
            variant="outline-secondary"
            onClick={addData}
          >
            쓰기
          </Button>
        </InputGroup>
        <List
          textList={textList}
          deleteData={deleteData}
          checkList={checkList}
          checkListBox={checkListBox}
        ></List>
        <div className="d-flex">
          <Button className="btn-dark ms-auto me-3" type="summit" onClick={saveData}>
            저장
          </Button>
        </div>
      </Container>
    </div>
  );
}

////////////////////////////// 글보이는곳 //////////////////////////////////////
function List({ textList, deleteData, checkList, checkListBox }) {
  return (
    <>
      <Container className="minhight">
        <Card className="mb-4 minhight">
          {textList.map((text, index) => {
            return (
              <Card.Body className="d-flex align-items-start  justify-content-space-between ">
                <InputGroup>
                  <InputGroup.Checkbox
                    checked={checkList[index]}
                    onChange={() => checkListBox(index)}
                  />
                  <Form.Control 
                    className= {`font2  ${checkList[index] ? "highlightGray middleline" : ""}`}
                    readOnly
                    value={text}
                  />
                  <button
                    className="btn btn-danger ms-auto"
                    style={{fontSize: "20px"}}
                    onClick={() => deleteData(index)}
                  >
                    X
                  </button>
                </InputGroup>
              </Card.Body>
            );
          })}
        </Card>
      </Container>
    </>
  );
}
