
import "./App.css";
import Calendar from 'react-calendar';
import { useEffect, useState } from 'react';
import "react-calendar/dist/Calendar.css";


import moment from 'moment';
import "./test.css";
import { Route, Routes, useNavigate, useParams } from "react-router-dom";
import { useCalendarFunctions,dailyData } from "./function/date";
import { SelectDate } from "./function/date";
import { Container } from "react-bootstrap";

function App() {
  let navigate = useNavigate();
  const [date,setDate]= useState(new Date());
  const [key,setKey] =useState([]);
 
  const {handleChange ,handleClickDay} = useCalendarFunctions(setDate,navigate);
   




  const dailyKey = dailyData();



 

  return (
    <div className="App">
      <Routes>
        <Route
          path="/"
          element={
            <Container className="calender-container">
              <Calendar
                className="calender "
                onChange={handleChange}
                value={date}
                tileClassName={({ date, view }) => {
                  let savedate = moment(date).format("YYYY-MM-DD");
                  if (dailyKey.find((x) => x === savedate)) {
                    let test = JSON.parse(localStorage.getItem(savedate));
                    if (test.checkList.every((value) => value == true)) {
                      return "highlightG";
                    } else if (
                      test.checkList.every((value) => value == false)
                    ) {
                      return "highlightR";
                    } else {
                      return "highlightY";
                    }
                  }
                }}
              ></Calendar>
            </Container>
          }
        ></Route>
        <Route path="/:date" element={<SelectDate></SelectDate>}></Route>
      </Routes>
    </div>
  );
  
}

export default App;
